// Code generated by internal/tools/tsgen from fog's Go structs. DO NOT EDIT.
// Change the Go struct (or its ts:"…" tag) and run `make gen-types`.

// AppSpec is one app's desired state. It is stored as JSON in app_revisions
// and NEVER contains secret values — only the names of secrets, whose values
// live encrypted in the secrets table.
export interface AppSpec {
  source: AppSource;
  env?: Record<string, string>;
  secrets?: string[]; // env var names whose values come from the vault
  volumes?: Volume[];
  files?: FileMount[];
  routes?: RouteSpec[];
  // Ports publishes raw container ports on the host — for non-HTTP
  // protocols the reverse proxy can't carry (DNS, SMTP). HTTP UIs belong
  // in Routes. Published ports force the "restart" deploy strategy: two
  // swap replicas can't bind the same host port.
  ports?: PortSpec[];
  health?: HealthSpec;
  command?: string[];
  // Processes are additional long-running processes sharing the app's
  // image, env, and volumes (e.g. Fin's solid_queue worker).
  processes?: ProcessSpec[];
  // Aux are sidecar containers the app needs beside it — its own database,
  // a Redis broker, an ML worker. They run their own images on a private
  // per-app network (reachable from the app by aux name, invisible to
  // other apps) and share the app's lifecycle, compose file, and backups.
  aux?: AuxService[];
  // Release runs once per deploy, from the new image, before processes
  // switch over — the migrations slot. Serialized by the app lock.
  release?: string[];
  // DeployStrategy: "swap" (default; start new web container, health-check,
  // flip the network alias, drain old — near-zero downtime) or "restart"
  // (compose recreate; simpler, brief downtime). Swap requires a health
  // spec and applies to the main process only.
  deployStrategy?: "swap" | "restart";
  // Needs declares managed datastores Fog provisions before deploying.
  needs?: AppNeeds;
  // Update policy for image-source apps: "manual" (default), "notify"
  // (badge + notification when the remote digest moves), or "auto"
  // (snapshot, apply, verify health, notify either way).
  updatePolicy?: "manual" | "notify" | "auto";
  // Backup: what a snapshot of this app includes. Managed volumes are
  // always included; databases adds pg_dump of managed databases.
  backup?: BackupSpec;
  // Notes: operator markdown shown on the app page (post-install steps,
  // runbook pointers).
  notes?: string;
  // Resources: conservative by design — memory limits only, no CPU limits
  // (long ffmpeg-style encodes must not be throttled into failure).
  memoryLimit?: string; // e.g. "2g"
  // Uses is what this app may read from fog's app-facing surface beyond
  // its own (docs/events-contract.md): "events" for the household event
  // stream, and the names of other apps whose Connection it is handed.
  // Installing an app with a uses list is the operator's grant — it sits
  // in the spec, so the app page shows it and every change is a revision.
  uses?: string[];
  // Reach names the other apps this app may call on the network
  // (netwire.go): the operator's approval, one provider at a time.
  // Connecting an integration adds its provider; an app in uses is
  // reached too. An env URL naming an app not approved here wires
  // nothing — the issues sweep asks instead.
  reach?: string[];
  // Connection is how another app reaches this one: its port on the fog
  // network and the vault secret holding the credential a consumer needs
  // (an API key, a long-lived token). Only apps that name this one in
  // their uses list ever see it.
  connection?: Connection;
  // Wants are the other apps this app can connect to
  // (docs/integrations-contract.md): its Integrations tab lists one entry
  // per app they name, and connecting one sets up everything its wants of
  // that app ask for. The operator still connects each.
  wants?: Want[];
  // Signin makes this app a client of fog's OpenID provider
  // (docs/signin-contract.md): the same block a git app puts in its
  // fog.yaml, for apps fog installs from an image (the catalog's
  // Paperless). Env values may name {{oidc.issuer}}, {{oidc.client_id}}
  // and {{oidc.client_secret}}, filled in at deploy.
  signin?: Manifest;
  // Network is which network the app lives on (docs/sealed-network.md):
  // empty for the shared fog network, or "sealed" for fog-sealed alone,
  // which has no route out of the machine. A sealed app's sidecars lose
  // their route too, and it can't publish host ports.
  network?: "sealed";
  // SealedPeer lets a sealed app be wired to this non-sealed one (by its
  // uses list or an env URL naming it; netwire.go), so it can reach it by
  // name. It keeps its way out, which makes it part of what a sealed app
  // trusts: anything it relays leaves the machine.
  sealedPeer?: boolean;
  // AcknowledgeHostAccess names, one by one, the host paths outside fog's
  // own storage (Drive, NAS shares, the app's data) this app binds
  // (hostaccess.go). Each must be spelled as the volume spells it; a
  // volume binding such a path without an entry here is refused, and an
  // entry that no volume binds is too. A few paths are never bound at
  // all: "/", /proc, /sys, /dev, a container runtime's socket, fog's data.
  acknowledgeHostAccess?: string[];
  // AcknowledgeRawSockets gives the app's containers CAP_NET_RAW, which
  // fog drops from every container by default: raw sockets forge
  // addresses on the app's network (ARP-spoofing its gateway, then
  // speaking as it to fog's proxy). Ping needs none — ICMP datagram
  // sockets don't. A DHCP server or a network scanner does.
  acknowledgeRawSockets?: boolean;
}

export interface AppStatus {
  // ID is the app's store row, so a caller joining other per-app reads
  // needn't list the apps again to map names to IDs.
  id: number;
  name: string;
  desiredState: string;
  state: string; // running | exited | missing | …
  detail: string; // "Up 2 hours"
  healthy?: boolean;
  // Summed over all of the app's running containers (see AppUsage), CPU
  // as a share of the whole host. Nil until the background sampler has a
  // fresh reading for one of them. Zero would be a claim — "this app is
  // using no CPU" — and the UI must be able to tell that apart from "we
  // haven't measured yet".
  cpuPercent?: number;
  memUsage?: number;
  // The containers' memory ceilings summed: the spec's limit where one is
  // set, otherwise the host's RAM, and never more than the host has —
  // the honest denominator for "1.4 / 8 GB".
  memLimit?: number;
  // Bytes per second between the sampler's last two readings, summed like
  // the rest. Nil until two readings exist for one of the containers.
  netInBps?: number;
  netOutBps?: number;
  diskReadBps?: number;
  diskWriteBps?: number;
  currentRev: number;
  image?: string;
  updateAvailable: boolean;
  // Short human-readable versions when an update is available: the running
  // commit/digest and the one waiting on the remote.
  updateFrom?: string;
  updateTo?: string;
  deploying: boolean;
  // An armed restore is staged in the app's volumes: it either has not been
  // consumed yet or the app is failing to consume it and retrying on every
  // boot. Reported from disk, so it survives a fogd restart — otherwise a
  // restore that outlives the process that started it becomes invisible,
  // and there is nothing on screen to cancel.
  restorePending: boolean;
  hostPort: number;
  // Every hostname the proxy serves this app on, resolved against the base
  // domain. Sent because a route may override the <app>.<domain> default —
  // callers that guess from the name alone are wrong for those apps. Empty
  // when the app has no routes or no base domain is configured yet.
  hosts?: string[];
  // Open+regressed Flare error groups. Nil when the count query failed —
  // absent, not zero, so the dashboard can't show a clean slate it hasn't
  // earned.
  openErrors?: number;
}

// GitInfo returns what the operator needs to wire up their git host.
export interface GitInfo {
  deployPublicKey: string;
  webhookPath: string;
}

// Diagnosis turns a raw failure log into a plain-English headline and fix.
// The operator should never need to read git/docker output to know what to
// do next; the raw log stays one click away for the rare unmatched case.
export interface Diagnosis {
  title: string;
  fix: string;
}

export interface AppContainer {
  // Found is false when no main container exists for the app (never
  // deployed, or removed). Every other field is then meaningless.
  found: boolean;
  id?: string;
  // Image is the reference the container runs (repo:tag); ImageID the
  // resolved digest-style ID behind it.
  image?: string;
  imageId?: string;
  state?: string;
  running: boolean;
  // RFC3339; StartedAt is the current run's start, FinishedAt the last
  // exit (empty while it has never exited).
  startedAt?: string;
  finishedAt?: string;
  // The last exit code. Only meaningful once FinishedAt is set; a
  // container that has never stopped reports 0 with no exit behind it.
  exitCode: number;
  oomKilled: boolean;
  restartCount: number;
  restartPolicy?: string;
  // The health check fog runs against it, and the day of results.
  health?: HealthSpec;
  healthEverySeconds: number;
  healthProbes: HealthProbe[];
  healthRetainHours: number;
}

// Review is everything about a spec that reaches past the app's own
// sandbox, laid out for an operator to read before the first deploy of an
// imported app: what it binds from the host, what it publishes, what it
// may read of other apps and of fog, and what it is acknowledged to do.
// Fog's spec has no privileged mode, devices, capabilities or host
// networking at all, so those never appear; anything that could stand in
// for them is here.
export interface AppReview {
  source: string; // image reference, or repo@branch
  mounts: ReviewMount[];
  ports: ReviewPort[];
  routes: ReviewRoute[];
  network: "shared" | "sealed";
  sealedPeer?: boolean;
  secrets: string[];
  // Env is the name of every variable the manifest sets — the app's, and
  // "<sidecar>: NAME" for a sidecar's. A name is what changes behaviour
  // (a preload, a proxy, a tool's setting), so it is shown.
  env: string[];
  // EnvLinks are the variables whose values name a place — a URL or a
  // host — as "NAME=value", any password in them masked: where the app
  // will try to connect, which the names alone don't say.
  envLinks: string[];
  // ReachAsked is the apps the manifest asks to call on the network
  // (AppSpec.Reach); confirming the review is the approval.
  reachAsked: string[];
  uses: string[];
  wants: string[];
  shares: string[];
  signin?: boolean;
  postgres?: boolean;
  execFiles: string[];
  release: string[];
  acknowledge: string[];
  // Reaches is the installed apps this one is wired to on the network —
  // its uses list and the apps an env URL names (Reaches in netwire.go)
  // — which is everything network isolation lets it talk to.
  reaches: string[];
  // RawSockets: the app keeps CAP_NET_RAW (acknowledgeRawSockets), with
  // which it can forge addresses on its network.
  rawSockets?: boolean;
  warnings: string[];
  // Leftovers is what an app deleted under this name, its data kept,
  // left behind — and this app would take over (Engine.Leftovers).
  // Confirming needs the operator's say-so to adopt it.
  leftovers: string[];
}

// importResult is what an import, or a look at a held app's review,
// answers: the review of one revision, and whether it still waits for a
// confirmation.
export interface AppImportResult {
  name: string;
  rev: number;
  review: AppReview;
  reviewPending: boolean;
}

